import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import { CardItem, Deck, Mana } from "../../../types";
import { Box, IconButton, Modal, Table, TableBody, TableCell, TableHead, TableRow, Typography } from "@mui/material";
import { Circle, Image } from "@mui/icons-material";
import CardComponent from "../../../components/CardComponent";

interface FullTableViewProps {
    deck: Deck;
    display: boolean;
}

const ColorlessMana = ({ count }: { count: number }): ReactElement => {
    return (
        <Box sx={{ position: "relative" }}>
            <Circle sx={{ color: "white" }} />
            <Box
                sx={{
                    height: "24px",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    position: "absolute",
                    color: "black",
                    top: 0,
                    bottom: 0,
                    left: 0,
                    right: 0,
                }}
            >
                {count}
            </Box>
        </Box>
    );
};

const FullTableView = observer((props: FullTableViewProps): ReactElement => {
    const { deck, display } = props;

    const [displayCard, setDisplayCard] = useState<CardItem | undefined>();

    const getColor = (mana: Mana) => {
        switch (mana) {
            case "B":
                return "./img/swamp.svg";
            case "G":
                return "./img/forest.svg";
            case "R":
                return "./img/mountain.svg";
            case "U":
                return "./img/island.svg";
            case "W":
                return "./img/plains.svg";
            default:
                return Number(mana);
        }
    };

    return (
        <>
            <Table stickyHeader sx={{ display: display ? undefined : "none" }}>
                <TableHead>
                    <TableRow>
                        <TableCell>
                            <Typography>Bild</Typography>
                        </TableCell>
                        <TableCell>
                            <Typography>Name</Typography>
                        </TableCell>
                        <TableCell>
                            <Typography>Mana</Typography>
                        </TableCell>
                        <TableCell>
                            <Typography>Durchschn. Bewertung</Typography>
                        </TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    {deck.cards.map((card) => {
                        const germanLanguage = card.foreignNames?.find((item) => item.language === "German");

                        const cardProps = germanLanguage ? { ...card, ...germanLanguage } : { ...card };

                        const getAverage = () => {
                            let sum = 0;
                            card.rating.forEach((rating) => {
                                sum += rating.count;
                            });
                            if (sum === 0) {
                                return null;
                            }
                            return (sum / card.rating.length).toFixed(2);
                        };
                        const mappedMana = card.manaCost?.split("}{").map((item) => {
                            return item.replace("{", "").replace("}", "");
                        }) as Mana[] | undefined;
                        return (
                            <TableRow>
                                <TableCell>
                                    <IconButton onClick={() => setDisplayCard(card)}>
                                        <Image />
                                    </IconButton>
                                </TableCell>
                                <TableCell>
                                    <Typography>{cardProps.name}</Typography>
                                </TableCell>
                                <TableCell>
                                    <Box display={"flex"}>
                                        {mappedMana?.map((mana) => {
                                            const result = getColor(mana);
                                            if (typeof result === "number") {
                                                return <ColorlessMana count={result} />;
                                            } else if (result.indexOf("img") !== -1) {
                                                return <img src={result} alt="icon" />;
                                            } else {
                                                return <Circle sx={{ color: result }} />;
                                            }
                                        })}
                                    </Box>
                                </TableCell>
                                <TableCell>
                                    <Typography>{getAverage() ?? "Kein Rating"}</Typography>
                                </TableCell>
                            </TableRow>
                        );
                    })}
                </TableBody>
            </Table>
            <Modal
                open={displayCard !== undefined}
                onClose={() => {
                    console.log("FIRE");
                    setDisplayCard(undefined);
                }}
                sx={{
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                }}
            >
                {/* <Box
                    sx={{
                        position: "absolute",
                        top: 0,
                        bottom: 0,
                        left: 0,
                        right: 0,
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                    }}
                > */}
                {displayCard ? <CardComponent withBackground card={displayCard} /> : <div />}
                {/* </Box> */}
            </Modal>
        </>
    );
});

export default FullTableView;
