import { observer } from "mobx-react";
import { ReactElement } from "react";
import { Deck } from "../../../types";
import { Grid, Table, TableBody, TableCell, TableFooter, TableHead, TableRow, Typography } from "@mui/material";
import CardComponent from "../../../components/CardComponent";
import { Star } from "@mui/icons-material";

interface DetailTableViewProps {
    deck: Deck;
    display: boolean;
}

const DetailTableView = observer((props: DetailTableViewProps): ReactElement => {
    const { deck, display } = props;

    return (
        <>
            {deck.cards.map((card) => {
                const getAverage = () => {
                    let sum = 0;
                    card.rating.forEach((rating) => {
                        sum += rating.count;
                    });
                    return (sum / card.rating.length).toFixed(2);
                };

                return (
                    <Grid container spacing={12} sx={{ width: "100%", display: display ? undefined : "none" }}>
                        <Grid size={6} sx={{ width: "300px", height: "420px" }}>
                            <CardComponent card={card} />
                            {/* <Box component={"img"} sx={{ width: "300px", height: "420px" }} src={card.imageUrl} /> */}
                        </Grid>
                        <Grid size={6}>
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell>
                                            <Typography>Datum</Typography>
                                        </TableCell>
                                        <TableCell>
                                            <Typography>Bewertung</Typography>
                                        </TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {card.rating.map((rating, index) => {
                                        const icons = [];
                                        for (let i = 0; i < rating.count; i++) {
                                            icons.push(<Star />);
                                        }
                                        return (
                                            <TableRow key={new Date(rating.date).toDateString() + index}>
                                                <TableCell sx={{ whiteSpace: "nowrap" }}>
                                                    {new Date(rating.date).toLocaleString()}
                                                </TableCell>
                                                <TableCell sx={{ width: "100%" }}>{icons}</TableCell>
                                            </TableRow>
                                        );
                                    })}
                                </TableBody>
                                <TableFooter>
                                    <TableRow>
                                        <TableCell colSpan={2}>
                                            <Typography>Durchschnitt: {getAverage()}</Typography>
                                        </TableCell>
                                    </TableRow>
                                </TableFooter>
                            </Table>
                        </Grid>
                    </Grid>
                );
            })}
        </>
    );
});

export default DetailTableView;
