import { observer } from "mobx-react";
import { ReactElement } from "react";
import { DeckType } from "../types";
import { Chip, SxProps } from "@mui/material";

const DeckTypeChip = observer((props: { type: DeckType; sx?: SxProps }): ReactElement => {
    const getColor = () => {
        switch (props.type) {
            case "Duel":
                return "primary";
            case "Commander":
                return "warning";
        }
    };

    return <Chip sx={props.sx} label={props.type} size="small" color={getColor()} />;
});

export default DeckTypeChip;
