import { Store } from "../../Store";
import { CardItem, Deck, DeckType } from "../../types";
import LocalStorageController from "../LocalStorageController";

export default class DecksController {
    private static instance: DecksController;
    private stores: Store;
    private constructor(stores: Store) {
        this.stores = stores;
    }

    public static getInstance = (stores: Store): DecksController => {
        if (DecksController.instance === undefined) {
            DecksController.instance = new DecksController(stores);
        }
        return DecksController.instance;
    };

    public addNewDeck = (name: string, type?: DeckType) => {
        const { decks, setDecks } = this.stores.decksStore;
        const newData: Deck[] = [...decks, { id: crypto.randomUUID(), name, cards: [], deckType: type }];
        LocalStorageController.getInstance(this.stores).saveData(newData);
        setDecks(newData);
    };

    public addToDeck = (card: CardItem, deckId: string): void => {
        const { decks, setDecks } = this.stores.decksStore;
        const updatedDecks: Deck[] = decks.map((deck) => {
            if (deck.id !== deckId) return deck;

            return { ...deck, cards: [...deck.cards, { ...card, rating: [] }] };
        });
        LocalStorageController.getInstance(this.stores).saveData(updatedDecks);
        setDecks(updatedDecks);
    };

    public updateRating = (deckId: string, cardId: string, rating: number) => {
        const { decks, setDecks } = this.stores.decksStore;
        const updatedDecks: Deck[] = decks.map((deck) => {
            if (deck.id !== deckId) return deck;

            return {
                ...deck,
                cards: deck.cards.map((card) => {
                    if (card.id !== cardId) return card;
                    const newRating = [...card.rating, { count: rating, date: new Date(Date.now()) }];
                    return { ...card, rating: newRating };
                }),
            };
        });
        LocalStorageController.getInstance(this.stores).saveData(updatedDecks);
        setDecks(updatedDecks);
    };

    public deleteCard = (deckId: string, cardId: string) => {
        const { decks, setDecks } = this.stores.decksStore;
        const updatedDecks: Deck[] = decks.map((deck) => {
            if (deck.id !== deckId) return deck;

            return {
                ...deck,
                cards: deck.cards.filter((card) => card.id !== cardId),
            };
        });
        LocalStorageController.getInstance(this.stores).saveData(updatedDecks);
        setDecks(updatedDecks);
    };
}
