import { Store } from "./Store";
import { CardItem, LoadingState } from "./types";

export default class ApiController {
    private static instance: ApiController;
    private stores: Store;

    private baseUrl = "https://api.magicthegathering.io/v1";

    private constructor(store: Store) {
        this.stores = store;
    }

    public static getInstance = (store: Store): ApiController => {
        if (ApiController.instance === undefined) {
            ApiController.instance = new ApiController(store);
        }
        return ApiController.instance;
    };

    public search = async (searchText: string): Promise<void> => {
        const { setLoadingState, setSearchResults } = this.stores.searchStore;
        if (searchText.trim().length === 0) return;
        setLoadingState(LoadingState.loading);
        const result = await fetch(this.baseUrl + "/cards?name=" + searchText + "&language=german");
        if (result && result.ok) {
            const parsed = (await result.json()) as { cards: CardItem[] };

            setLoadingState(LoadingState.loaded);
            setSearchResults(parsed.cards);
        } else {
            setLoadingState(LoadingState.failed);
        }
    };
}
