/* eslint-disable react-hooks/exhaustive-deps */
import { useRef } from "react";
import { Box, createTheme, ThemeProvider as MuiThemeProvider } from "@mui/material";
import "./main.css";
import SearchSite from "./sites/search/SearchSite";
import DecksSite from "./sites/decks/DecksSite";
import RatingSite from "./sites/rating/RatingSite";
import { Sites } from "./types";
import StatisticsSite from "./sites/statistics/StatisticsSite";
import useStores from "./Store";
import Notifications from "./components/Notifications";
import UploadDialog from "./components/UploadDialog";
import MenuDrawer from "./components/MenuDrawer";
import { observer } from "mobx-react";
import NavBar from "./components/NavBar";

const App = observer(() => {
    const theme = createTheme({ palette: { mode: "dark" } });
    const stores = useStores();
    const { activeSite, possibleDecksToUpload, setPossibleDecksToUpload, setMenuOpen } = stores;

    const background = useRef(["forest", "island", "mountain", "plains", "swamp"][Math.round(Math.random() * 4)]);

    return (
        <MuiThemeProvider theme={theme}>
            <NavBar />
            <Box
                sx={{
                    flex: 1,
                    display: "flex",
                    flexDirection: "column",
                    height: "100%",
                    minHeight: 0,
                    "&:before": {
                        content: '""',
                        background: `linear-gradient(rgba(0,0,0,0.5),rgba(0,0,0,0.5)),url(./img/${background.current}.png)`,
                        backgroundPosition: "center",
                        backgroundRepeat: "no-repeat",
                        backgroundAttachment: "fixed",
                        backgroundSize: "cover",
                        opacity: 0.1,
                        position: "absolute",
                        pointerEvents: "none",
                        left: 0,
                        top: 0,
                        right: 0,
                        bottom: 0,
                    },
                }}
            >
                {activeSite === Sites.Search && <SearchSite display={activeSite === "search"} />}
                {activeSite === Sites.Decks && <DecksSite display={activeSite === "decks"} />}
                {activeSite === Sites.Rating && <RatingSite display={activeSite === "rating"} />}
                {activeSite === Sites.Statistics && <StatisticsSite display={activeSite === "statistics"} />}
                {possibleDecksToUpload !== undefined && (
                    <UploadDialog
                        handleClose={() => {
                            setPossibleDecksToUpload(undefined);
                            setMenuOpen(false);
                        }}
                        possibleDecks={possibleDecksToUpload}
                    />
                )}
                <MenuDrawer />
                <Notifications />
            </Box>
        </MuiThemeProvider>
    );
});

export default App;
