import { observer } from "mobx-react";
import { ReactElement } from "react";
import useStores from "../Store";
import { Drawer, List, ListItem, ListItemButton, ListItemIcon, ListItemText } from "@mui/material";
import { BarChart, Check, Search, StarHalf, WebStories } from "@mui/icons-material";
import { Sites } from "../types";

const MenuDrawer = observer((): ReactElement => {
    const stores = useStores();
    const { menuOpen, setMenuOpen, activeSite, setActiveSite } = stores;

    const values = [
        { value: Sites.Search, text: "Suche", icon: <Search /> },
        { value: Sites.Decks, text: "Decks", icon: <WebStories /> },
        { value: Sites.Rating, text: "Rating", icon: <StarHalf /> },
        { value: Sites.Statistics, text: "Statistik", icon: <BarChart /> },
    ];

    return (
        <Drawer open={menuOpen} onClose={() => setMenuOpen(false)} anchor="top">
            <List>
                {values.map((v) => {
                    return (
                        <ListItem key={v.text} secondaryAction={activeSite === v.value ? <Check /> : undefined}>
                            <ListItemButton
                                onClick={() => {
                                    setActiveSite(v.value);
                                    setMenuOpen(false);
                                }}
                                disabled={activeSite === v.value}
                            >
                                <ListItemIcon>{v.icon}</ListItemIcon>
                                <ListItemText primary={v.text} />
                            </ListItemButton>
                        </ListItem>
                    );
                })}
            </List>
        </Drawer>
    );
});

export default MenuDrawer;
