import { SkipNext, Star } from "@mui/icons-material";
import { Box, Button, ButtonGroup, ToggleButton, ToggleButtonGroup, Typography } from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import useStores from "../../Store";
import DecksController from "../decks/DecksController";
import CardComponent from "../../components/CardComponent";

const RatingSite = observer(({ display }: { display: boolean }): ReactElement => {
    const stores = useStores();

    const { activeDeckId } = stores;
    const { decks } = stores.decksStore;

    const activeDeck = decks.length > 0 ? decks.find((deck) => deck.id === activeDeckId) : undefined;
    const [stars, setStars] = useState([0]);
    const [cardIndex, setCardIndex] = useState(0);

    const decksController = DecksController.getInstance(stores);

    const handleRatingChange = (newValue: number) => {
        const newList = [];
        for (let i = 1; i <= newValue; i++) {
            newList.push(i);
        }
        setStars(newList);
    };

    return (
        <Box sx={{ flex: 1, display: display ? "flex" : "none", justifyContent: "center", alignItems: "center" }}>
            {activeDeck?.cards.map((card, index) => {
                return (
                    <Box sx={{ display: index === cardIndex ? undefined : "none", position: "relative" }}>
                        <CardComponent card={card} />
                        <Box
                            sx={{
                                display: "flex",
                                gap: "1rem",
                                mt: "1rem",
                                // position: "absolute",
                                // bottom: "-3rem",
                                width: "100%",
                                justifyContent: "center",
                            }}
                        >
                            <ToggleButtonGroup
                                exclusive
                                value={stars}
                                onChange={(e, v) => {
                                    handleRatingChange(v);
                                }}
                            >
                                <ToggleButton value={1}>
                                    <Star />
                                </ToggleButton>
                                <ToggleButton value={2}>
                                    <Star />
                                </ToggleButton>
                                <ToggleButton value={3}>
                                    <Star />
                                </ToggleButton>
                                <ToggleButton value={4}>
                                    <Star />
                                </ToggleButton>
                                <ToggleButton value={5}>
                                    <Star />
                                </ToggleButton>
                            </ToggleButtonGroup>
                            <ButtonGroup>
                                <Button
                                    onClick={() => {
                                        if (!activeDeck) return;
                                        decksController.updateRating(activeDeck.id, card.id, stars.slice().sort((a, b) => b - a)[0]);
                                        setStars([0]);
                                        setCardIndex(cardIndex + 1);
                                    }}
                                >
                                    <SkipNext />
                                </Button>
                            </ButtonGroup>
                        </Box>
                    </Box>
                );
            })}
            {activeDeck && cardIndex >= activeDeck.cards.length && <Typography>Ende des Decks</Typography>}
        </Box>
    );
});

export default RatingSite;
