import { action, makeObservable, observable } from "mobx";
import { Deck } from "../../types";

export default class DecksStore {
    public decks: Deck[] = [];

    constructor() {
        makeObservable(this, {
            decks: observable,
            setDecks: action,
        });
    }

    public setDecks = (newValue: Deck[]) => {
        this.decks = newValue;
    };
}
