import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import { CardItem, RatedCardItem } from "../types";
import { Box, Card, Divider, SxProps, Typography } from "@mui/material";
import ReactCardFlip from "react-card-flip";
import Neumorphism from "./Neumorphism";

interface CardComponentProps {
    card: CardItem | RatedCardItem;
    withBackground?: boolean;
}

const CardComponent = observer((props: CardComponentProps): ReactElement => {
    const { card, withBackground } = props;

    const [isFlipped, setIsFlipped] = useState<boolean>(false);

    const germanLanguage = card.foreignNames?.find((item) => item.language === "German");

    const cardProps = germanLanguage ? { ...card, ...germanLanguage } : { ...card };

    return (
        <Box
            sx={{
                position: "relative",
            }}
        >
            <Box
                sx={{
                    width: "300px",
                    height: "420px",
                }}
            >
                <ReactCardFlip isFlipped={isFlipped}>
                    {cardProps.imageUrl ? (
                        <Box
                            onClick={() => setIsFlipped(!isFlipped)}
                            sx={
                                {
                                    width: "300px",
                                    height: "420px",
                                    cursor: "pointer",
                                    borderRadius: "16px",
                                    transition: "0.2s",
                                    ...Neumorphism.outsetShadow,
                                    "&:hover": Neumorphism.outsetShadowStrong,
                                } as SxProps
                            }
                            component={"img"}
                            loading="lazy"
                            src={cardProps.imageUrl}
                        />
                    ) : (
                        <Card
                            onClick={() => setIsFlipped(!isFlipped)}
                            sx={{
                                width: "300px",
                                height: "420px",
                                cursor: "pointer",
                                display: "flex",
                                borderRadius: "16px",
                                justifyContent: "center",
                                alignItems: "center",
                                ...Neumorphism.outsetShadow,
                            }}
                        >
                            <Typography>kein Bild</Typography>
                        </Card>
                    )}
                    <Card
                        sx={{
                            width: "300px",
                            height: "420px",
                            cursor: "pointer",
                            p: "0.5rem",
                            display: "flex",
                            borderRadius: "16px",
                            flexDirection: "column",
                            ...Neumorphism.CardStyles,
                            background: withBackground ? "linear-gradient(145deg, #25272b, #25272b)" : undefined,
                        }}
                        onClick={() => setIsFlipped(!isFlipped)}
                    >
                        <Typography variant="h6">{cardProps.name}</Typography>
                        <Divider sx={{ m: "0.5rem" }} />
                        <Typography variant="subtitle1" sx={Neumorphism.TypographyStyles.inset}>
                            {cardProps.type}
                        </Typography>
                        <Typography sx={{ mt: "0.5rem", ...Neumorphism.TypographyStyles.inset }}>{cardProps.text}</Typography>
                        <Box
                            sx={{
                                display: "flex",
                                alignItems: "flex-end",
                                justifyContent: "flex-end",
                                mt: "auto",
                            }}
                        >
                            <Typography variant="caption" fontStyle="italic">
                                {cardProps.flavor}
                            </Typography>
                            {cardProps.loyalty && <Typography sx={{ m: "0.5rem" }}>{cardProps.loyalty}</Typography>}
                            {cardProps.power && cardProps.toughness && (
                                <Typography sx={{ m: "0.5rem" }}>{cardProps.power + "/" + cardProps.toughness}</Typography>
                            )}
                        </Box>
                    </Card>
                </ReactCardFlip>
            </Box>
        </Box>
    );
});

export default CardComponent;
