import { SxProps } from "@mui/material";

const outsetShadow = "5px 5px 8px #16171a, -5px -5px 8px #34373c";
const outsetShadowStrong = "10px 10px 10px #16171a, -10px -10px 10px #34373c";
const outsetShadowSoft = "3px 3px 5px #16171a, -3px -3px 5px #34373c";
const insetShadow = "inset 8px 8px 10px #16171a, inset -8px -8px 10px #34373c";
const insetShadowSoft = "inset 3px 3px 10px #16171a, inset -3px -3px 10px #34373c";

type NeumorphismType = {
    insetShadow: SxProps;
    outsetShadow: SxProps;
    outsetShadowStrong: SxProps;
    TextFieldStyles: SxProps;
    ButtonStyles: SxProps;
    SelectStyles: SxProps;
    MenuStyles: SxProps;
    TypographyStyles: { inset: SxProps; outset: SxProps };
    CardStyles: SxProps;
};

const Neumorphism: NeumorphismType = {
    insetShadow: { boxShadow: insetShadow },
    outsetShadow: { boxShadow: outsetShadow },
    outsetShadowStrong: { boxShadow: outsetShadowStrong },
    TextFieldStyles: {
        boxShadow: insetShadow,
        borderRadius: "4px",
        "& fieldset": { border: "none !important" },
        "& .MuiInputBase-root": {
            background: "none",
            ":after, :before": {
                border: "none !important",
            },
        },
        "& .MuiInputBase-input": {
            "&:-webkit-autofill": {
                transition: "background-color 0s 600000s, color 0s 600000s !important",
                webkitBoxShadow: insetShadow,
            },
        },
    },
    ButtonStyles: {
        boxShadow: outsetShadow,
        ":hover": { boxShadow: insetShadowSoft },
        //border: "1px solid #353535",
    },
    SelectStyles: {
        boxShadow: insetShadow,
        "&.MuiInputBase-root": { background: "none", ":after, :before": { border: "none !important" } },
        "& fieldset": { border: "none" },
    },
    MenuStyles: { "& .MuiPaper-root": { boxShadow: insetShadow } },
    TypographyStyles: {
        inset: {
            //border: "1px solid #353535",
            p: "0.3rem",
            // m: "0.3rem",
            boxShadow: insetShadow,
            borderRadius: "4px",
        },
        outset: {
            //border: "1px solid #353535",
            p: "0.3rem",
            // m: "0.3rem",
            boxShadow: outsetShadowSoft,
            borderRadius: "4px",
        },
    },
    CardStyles: { background: "none", boxShadow: insetShadow },
};

export default Neumorphism;
